<?php require __DIR__.'/../app/bootstrap.php';require_login();require_permission('notifications.view');verify_csrf();$rows=$pdo->query("SELECT ss.*,u.unit_code,u.current_meter FROM service_schedules ss JOIN units u ON u.id=ss.unit_id WHERE ss.next_service_date<=DATE_ADD(CURDATE(),INTERVAL 7 DAY) OR u.current_meter>=ss.next_service_meter-50")->fetchAll();foreach($rows as $r){$status=service_status((float)$r['current_meter'],(float)$r['next_service_meter'],$r['next_service_date']);$pdo->prepare('UPDATE service_schedules SET status=? WHERE id=?')->execute([$status,$r['id']]);$title=$status==='Terlambat'?'Service Terlambat':'Service Segera Jatuh Tempo';$exists=$pdo->prepare("SELECT COUNT(*) FROM notifications WHERE type='service' AND message LIKE ? AND DATE(created_at)=CURDATE()");$exists->execute(['%'.$r['unit_code'].'%']);if(!$exists->fetchColumn())notify($pdo,null,'service',$title,'Unit '.$r['unit_code'].' status '.$status.'; meter '.$r['current_meter'].' dari target '.$r['next_service_meter'],page_url('maintenance'));}audit($pdo,'GENERATE','notification',null,'Generate notifikasi service');flash('success','Notifikasi service diperbarui.');redirect('../'.page_url('notifications'));
